export type LessonSection = { title: string; body: string; code?: string; note?: string };
export type Lesson = { slug: string; title: string; summary: string; minutes: number; objectives: string[]; sections: LessonSection[]; exercise: { prompt: string; requirements: string[]; solution: string }; quiz: { question: string; options: string[]; answer: number; explanation: string }[]; references: { label: string; url: string }[] };
export type Course = { slug: string; title: string; category: string; level: string; summary: string; description: string; prerequisites: string[]; outcomes: string[]; lessons: Lesson[]; project: { title: string; brief: string; requirements: string[] } };

export const courses: Course[] = [{
slug:"html",title:"HTML Foundations",category:"Web development",level:"Beginner",
summary:"Learn to structure clear, accessible web pages with semantic HTML.",
description:"A complete beginner-to-intermediate HTML programme covering document foundations, text, links, media, tables, semantic structure, forms, accessibility, metadata, validation, security and a guided capstone website project.",
prerequisites:["No programming experience required.","A modern browser and a code editor such as VS Code."],
outcomes:["Understand HTML syntax, elements, attributes and the browser DOM.","Build multi-page documents with semantic structure and navigation.","Work with text, links, images, tables, figures, audio and video.","Create accessible forms and native interactive components.","Write metadata, validate markup and debug browser output.","Apply accessibility, privacy and safe-embedding practices.","Plan, build and review a complete personal website."],
project:{title:"Build a personal profile page",brief:"Create a one-page profile that introduces a person, highlights their interests and gives visitors a useful way to get in touch.",requirements:["Use a valid HTML document structure.","Include one clear page heading and a logical heading hierarchy.","Add an about section and a list of interests.","Include at least two useful links.","Add an image with meaningful alternative text, or empty alt text for a decorative image.","Use semantic landmarks and a labelled contact form."]},
lessons:[
{slug:"html-document-structure",title:"How an HTML document works",summary:"Understand elements, tags, attributes and the minimum structure every page needs.",minutes:12,objectives:["Describe HTML's role in the browser.","Recognise elements, tags and attributes.","Create a valid document skeleton."],sections:[
{title:"HTML gives content its structure",body:"HTML stands for HyperText Markup Language. It describes what content means and how pieces of a document relate to one another. A browser reads HTML and builds a document tree that other browser technologies can work with. HTML is not a programming language: it does not provide general-purpose loops or calculations. CSS controls presentation, while JavaScript adds behaviour. Keeping these responsibilities distinct makes websites easier to understand and maintain."},
{title:"Elements, tags and attributes",body:"An HTML element usually has an opening tag, content and a closing tag. The tags mark the beginning and end; the complete element includes everything between them. Attributes add information to an element. For example, the lang attribute on html identifies the document's language. Some elements, such as img and meta, are void elements: they do not wrap content and must not have closing tags."},
{title:"The document skeleton",body:"A page begins with a doctype declaration, followed by the root html element. The head contains metadata that describes the document. The body contains the content presented in the page. A useful page title belongs in the head and appears in the browser tab, history and search previews.",code:'<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1">\n    <title>My first page</title>\n  </head>\n  <body>\n    <h1>Hello, web</h1>\n    <p>This is my first HTML page.</p>\n  </body>\n</html>'},
{title:"What the browser does",body:"The browser parses the markup and creates the Document Object Model (DOM), a tree representation of the page. The DOM is what browser tools and JavaScript can inspect. Browsers are forgiving and often attempt to recover from malformed markup, but a page that happens to render is not necessarily well-structured. Use the browser's developer tools and an HTML validator to catch mistakes early.",note:"Save the example as index.html and open it directly in a browser. Change the title and heading, save, then refresh to see which parts of the page each element controls."}],
exercise:{prompt:"Create an HTML file for a page introducing your favourite subject.",requirements:["Start with the HTML doctype.","Set the document language to English.","Add UTF-8 character encoding and a responsive viewport meta tag.","Give the page a descriptive title.","Add one h1 and one paragraph inside body."],solution:'<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Why I enjoy astronomy</title>\n</head>\n<body>\n  <h1>Why I enjoy astronomy</h1>\n  <p>Astronomy helps me understand the universe.</p>\n</body>\n</html>'},
quiz:[{question:"Which element contains the content displayed in the page?",options:["head","body","title","meta"],answer:1,explanation:"The body contains the document's visible content. The head contains metadata and supporting information."},{question:"What does the lang attribute on html communicate?",options:["The page's colour scheme","The browser brand","The document's language","The page's URL"],answer:2,explanation:"The lang attribute identifies the primary language of the document, helping assistive technology and other tools interpret it."}],
references:[{label:"MDN: Getting started with HTML",url:"https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started/Your_first_website/Creating_the_content"},{label:"WHATWG HTML Living Standard",url:"https://html.spec.whatwg.org/"}]},
{slug:"headings-paragraphs-lists",title:"Headings, paragraphs and lists",summary:"Organise information into readable sections and meaningful groups.",minutes:10,objectives:["Use headings to express document hierarchy.","Write paragraphs for coherent ideas.","Choose ordered and unordered lists appropriately."],sections:[
{title:"Headings describe structure",body:"HTML provides six heading levels, from h1 to h6. Use them to describe the hierarchy of your content, not simply to make text look large. A page normally has one main h1 that describes its central topic. Major sections use h2; subsections within them use h3. Do not skip levels just to obtain a particular visual size. CSS should control appearance."},
{title:"Paragraphs group related sentences",body:"The p element represents a paragraph. Use a new paragraph when the idea changes or a long block becomes difficult to scan. Do not use repeated br elements to create visual spacing between paragraphs; use separate paragraph elements and style their margins with CSS."},
{title:"Lists make relationships clear",body:"Use ul for a group where order does not matter, such as a shopping list. Use ol when sequence matters, such as instructions. Each item belongs in an li element. A description list (dl) is useful for terms and their descriptions.",code:'<h1>Plan a study session</h1>\n<p>Use this checklist to prepare.</p>\n<h2>Before you begin</h2>\n<ul><li>Choose one topic.</li><li>Gather your notes.</li><li>Silence notifications.</li></ul>\n<h2>Study sequence</h2>\n<ol><li>Review the concept.</li><li>Work through an example.</li><li>Try a practice question.</li></ol>'},
{title:"A hierarchy is not a design shortcut",body:"A logical heading outline helps people scan a page and helps assistive technology users navigate between sections. It also makes the document easier for future authors to maintain. If you need a heading to appear smaller, choose the correct semantic level and style it with a class rather than selecting a heading level based on its default font size.",note:"Try reading only the headings in your page. They should form a useful outline that explains the page without requiring every paragraph."}],
exercise:{prompt:"Write a short packing checklist for a weekend trip.",requirements:["Use one h1 for the page title.","Add an h2 for at least two sections.","Use an unordered list for items to pack.","Use an ordered list for preparation steps."],solution:'<h1>Weekend trip checklist</h1>\n<h2>What to pack</h2>\n<ul><li>Clothes</li><li>Toiletries</li><li>Phone charger</li></ul>\n<h2>Before leaving</h2>\n<ol><li>Check the weather.</li><li>Confirm your booking.</li><li>Lock the doors.</li></ol>'},
quiz:[{question:"Which list element is best when the order of items matters?",options:["ul","ol","dl","li"],answer:1,explanation:"An ordered list (ol) communicates a sequence or ranking. An unordered list is for groups without a meaningful order."},{question:"Why should heading levels follow a logical hierarchy?",options:["To make all text bold","To create a navigable document outline","To avoid using CSS","To make the page load faster"],answer:1,explanation:"Heading levels communicate relationships between sections and support navigation for readers and assistive technology."}],
references:[{label:"MDN: HTML text fundamentals",url:"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content/HTML_text_fundamentals"}]},
{slug:"links-and-images",title:"Links and images",summary:"Connect pages and add images without losing context or accessibility.",minutes:12,objectives:["Create links with the anchor element.","Understand relative and absolute URLs.","Add images with appropriate alternative text."],sections:[
{title:"Links connect the web",body:"The anchor element (a) creates a hyperlink when it has an href attribute. The destination can be an absolute URL, such as an external website, or a relative URL that points to another location in your own site. Link text should describe the destination or action. Phrases such as click here provide little context when read out of a list of links.",code:'<p>Read the <a href="/learn/html">HTML course overview</a>.</p>\n<p>Reference: <a href="https://developer.mozilla.org/en-US/docs/Web/HTML">MDN HTML docs</a>.</p>'},
{title:"Understand paths",body:"A root-relative path begins with a slash and is resolved from the website root, for example /about/. A document-relative path is resolved from the current page location, for example ../images/logo.svg. Absolute URLs include the scheme and host. Choose paths deliberately and test links after moving files or changing routes."},
{title:"Images need text alternatives",body:"The img element embeds an image. Its src identifies the resource and its alt attribute provides a text alternative. If an image communicates information, describe the information that matters in context. If it is purely decorative and adds no information, use an empty alt attribute so assistive technology can skip it. Do not use a filename as alt text.",code:'<img src="/images/team-workshop.jpg"\n     alt="Three students collaborating around a laptop">'},
{title:"Make external links predictable",body:"If a link opens a new tab with target blank, tell users when that behaviour matters. Modern browsers implicitly apply relevant opener protection to target blank links, but explicitly writing rel noopener noreferrer remains a clear defensive convention. Do not open every link in a new tab; let people decide how they want to navigate.",note:"An image with an empty alt attribute is not missing accessibility text when the image is decorative. The choice depends on the image's purpose in that particular page."}],
exercise:{prompt:"Create a small resources section with one internal link, one external link and one image.",requirements:["Use descriptive link text.","Use a relative or root-relative URL for the internal link.","Use a full HTTPS URL for the external link.","Give the image useful alt text, or empty alt text if decorative."],solution:'<section>\n  <h2>Useful resources</h2>\n  <p><a href="/learn/html">Continue the HTML course</a></p>\n  <p><a href="https://developer.mozilla.org/en-US/docs/Web/HTML">Read MDN HTML guide</a></p>\n  <img src="/images/study-group.jpg" alt="Learners reviewing code together">\n</section>'},
quiz:[{question:"What does the alt attribute provide for an informative image?",options:["A visible caption in every browser","A text alternative describing relevant information","A smaller image file","A link destination"],answer:1,explanation:"Alt text communicates the important information conveyed by an image when it cannot be seen or loaded."},{question:"Which link text is most useful out of context?",options:["Click here","More","Read the HTML course outline","This"],answer:2,explanation:"Descriptive link text communicates the destination and makes link lists more understandable."}],
references:[{label:"MDN: Creating hyperlinks",url:"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content/Creating_links"},{label:"W3C WAI: Images tutorial",url:"https://www.w3.org/WAI/tutorials/images/"}]},
{slug:"semantic-html",title:"Semantic HTML and page landmarks",summary:"Choose elements by meaning and give pages a navigable structure.",minutes:14,objectives:["Explain semantic HTML.","Use header, nav, main, section and footer appropriately.","Distinguish buttons from links."],sections:[
{title:"Meaning before appearance",body:"Semantic HTML uses elements that describe the role of their content. A nav element identifies a major navigation area; main identifies the page's dominant content; article represents a self-contained composition; and footer contains information about its nearest section or page. These elements give browsers, assistive technologies and developers a shared understanding of the page."},
{title:"Build with landmarks",body:"A typical page can have a site header, primary navigation, one main region and a footer. Use section for a thematic grouping, usually with a heading. Use article when the content could stand on its own, such as a news story or forum post. Avoid choosing semantic elements merely because their default display style looks convenient.",code:'<header><a href="/">Site name</a></header>\n<nav aria-label="Primary"><a href="/courses">Courses</a></nav>\n<main><article><h1>Learning HTML</h1>\n<section><h2>Why semantics matter</h2><p>Meaningful structure helps everyone navigate.</p></section>\n</article></main>\n<footer>Copyright information</footer>'},
{title:"Links navigate; buttons perform actions",body:"Use an anchor when activating it takes the user to a URL. Use a button when it performs an action on the current page, such as opening a dialog, submitting a form or toggling a setting. Replacing these with generic div elements removes built-in keyboard and accessibility behaviour and creates extra work."},
{title:"Use ARIA only when native HTML is not enough",body:"Native semantic elements should be your first choice. ARIA can add accessible names or relationships when needed, but it cannot repair every poorly structured interface. A labelled navigation landmark can distinguish primary navigation from footer navigation. A button already has button semantics; adding role button to it is unnecessary.",note:"A good semantic page remains understandable when CSS is disabled. Try turning off styles in developer tools and inspect whether the document still has a clear structure."}],
exercise:{prompt:"Restructure a simple page using semantic landmarks.",requirements:["Add a header containing the site identity.","Add a nav with an accessible label.","Place the main content inside main.","Use article for a self-contained tutorial.","Add a footer outside main."],solution:'<header><a href="/">B Tecky</a></header>\n<nav aria-label="Primary"><a href="/learn">Learn</a></nav>\n<main><article><h1>HTML semantics</h1><p>Meaningful elements explain content roles.</p></article></main>\n<footer>More learning resources</footer>'},
quiz:[{question:"Which element should identify the dominant content of the current page?",options:["main","aside","footer","small"],answer:0,explanation:"The main element represents the dominant content of the document body."},{question:"When should you use a button instead of an anchor?",options:["Whenever text is underlined","When performing an action without navigating to a URL","For every external website","To create a heading"],answer:1,explanation:"Buttons perform actions. Anchors navigate to a resource or URL."}],
references:[{label:"MDN: HTML semantics",url:"https://developer.mozilla.org/en-US/docs/Glossary/Semantics#semantics_in_html"},{label:"W3C WAI: Page structure",url:"https://www.w3.org/WAI/tutorials/page-structure/"}]},
{slug:"forms-and-labels",title:"Forms, labels and input basics",summary:"Collect information with native controls and accessible labels.",minutes:15,objectives:["Explain the role of a form.","Associate labels with controls.","Choose suitable input types and required fields."],sections:[
{title:"Forms collect user input",body:"The form element groups controls that submit information. Each control needs a meaningful name so its value can be identified when submitted. The action attribute identifies the destination and method describes how the browser sends the form data. A static HTML page can demonstrate the structure, but a real form also needs a server or service to receive and process submissions."},
{title:"Labels are essential",body:"A visible label tells users what information a control expects. Connect it to an input using matching for and id values. Clicking the label then focuses or activates its control, and assistive technology can announce the label with the field.",code:'<form action="/contact" method="post">\n  <label for="name">Your name</label>\n  <input id="name" name="name" autocomplete="name" required>\n  <label for="email">Email address</label>\n  <input id="email" name="email" type="email" autocomplete="email" required>\n  <button type="submit">Send message</button>\n</form>'},
{title:"Choose the right control",body:"Use type email for email addresses, type tel for telephone numbers, and type password for password entry. Use textarea for longer text and select when users choose from a set of options. Native input types can provide useful validation and mobile keyboard hints, but they do not replace server-side validation."},
{title:"Validation and privacy",body:"The required attribute can prevent a form from being submitted while a required field is empty. Other constraints such as minlength and maxlength can improve feedback. Client-side validation is for usability, not security: a server must validate incoming data independently. Ask only for information the task genuinely requires and explain how it will be used.",note:"Never collect sensitive information in a demo form. A front-end example is not a secure storage or authentication system."}],
exercise:{prompt:"Create a feedback form for a learning lesson.",requirements:["Add a form with a POST method and a clearly described action.","Include a required name field with a matching label.","Include a required email field using type email.","Include a textarea with a matching label.","Add a submit button."],solution:'<form action="/feedback" method="post">\n  <label for="learner-name">Name</label>\n  <input id="learner-name" name="name" required>\n  <label for="learner-email">Email</label>\n  <input id="learner-email" name="email" type="email" required>\n  <label for="feedback">Your feedback</label>\n  <textarea id="feedback" name="feedback" rows="4"></textarea>\n  <button type="submit">Send feedback</button>\n</form>'},
quiz:[{question:"How should a label be associated with an input?",options:["Give both the same name attribute","Match the label for value to the input id","Put the label after the form","Use placeholder text only"],answer:1,explanation:"The label's for attribute must match the form control's id. This creates a programmatic association and makes the label clickable."},{question:"Why is browser-side validation not enough to secure a form?",options:["It only works on desktop","Users can bypass or modify client-side checks","It changes the page title","It prevents keyboard use"],answer:1,explanation:"Client-side checks can be bypassed. The receiving server must validate and safely handle all submitted data."}],
references:[{label:"MDN: Your first form",url:"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Forms/Your_first_form"},{label:"W3C WAI: Forms concepts",url:"https://www.w3.org/WAI/tutorials/forms/"}]}
]}];



// Extended HTML curriculum: the first five lessons establish the basics; these
// modules take learners through real-world document authoring and quality.
const extendedHtmlLessons: Lesson[] = [
{
slug:"tables-and-tabular-data",title:"HTML tables and tabular data",summary:"Represent genuine row-and-column data with accessible table structure.",minutes:18,
objectives:["Recognise when data belongs in a table.","Use caption, thead, tbody, tr, th and td correctly.","Associate headers with data cells."],
sections:[
{title:"Tables are for data, not page layout",body:"An HTML table represents information with relationships across rows and columns. Examples include a class timetable, product comparison or monthly budget. Tables should not be used to position page elements: CSS layout tools are more flexible and keep the document structure meaningful. Before creating a table, ask whether readers need to compare values by row and column. If not, headings, lists or paragraphs may communicate the information more clearly."},
{title:"Build the table structure",body:"The table element contains rows. A caption gives the table a useful name. The thead and tbody elements group header and body rows, while tr represents each row. Use th for a header cell and td for ordinary data. The scope attribute can clarify whether a header applies to a row or column. Keep the structure simple whenever possible.",code:'<table>\n  <caption>Workshop schedule</caption>\n  <thead><tr><th scope="col">Time</th><th scope="col">Topic</th></tr></thead>\n  <tbody>\n    <tr><th scope="row">09:00</th><td>HTML basics</td></tr>\n    <tr><th scope="row">10:00</th><td>Semantic markup</td></tr>\n  </tbody>\n</table>'},
{title:"Headers make relationships understandable",body:"A table can be visually obvious to a sighted reader while its relationships remain unclear to someone using a screen reader. Header cells communicate the labels associated with values. Use scope col for column headers and scope row for row headers in straightforward tables. Complex tables with multi-level headers may need explicit id and headers associations; consider whether splitting the data into simpler tables would be clearer."},
{title:"Keep tables readable",body:"Avoid empty rows or columns used only for spacing. Do not place unrelated content into one table just because it fits the grid. On narrow screens, wide data tables may need a horizontally scrollable wrapper, but preserve access to all content and provide a clear indication that horizontal scrolling is available.",note:"Try navigating the table using a screen reader or keyboard. The row and column labels should make each value understandable."}],
exercise:{prompt:"Create a two-column table showing at least three learning topics and the time needed for each.",requirements:["Add a caption.","Use a thead with column headers.","Use tbody for data rows.","Use th with scope for row labels and td for values."],solution:'<table>\n<caption>Study plan</caption>\n<thead><tr><th scope="col">Topic</th><th scope="col">Minutes</th></tr></thead>\n<tbody><tr><th scope="row">HTML</th><td>30</td></tr><tr><th scope="row">CSS</th><td>45</td></tr><tr><th scope="row">Practice</th><td>20</td></tr></tbody>\n</table>'},
quiz:[{question:"What is the main purpose of an HTML table?",options:["Page layout","Tabular data with row and column relationships","Decorative borders","A navigation menu"],answer:1,explanation:"Tables are for data where relationships across rows and columns matter."},{question:"Which attribute can identify a column header?",options:["scope=\"col\"","alt","placeholder","target"],answer:0,explanation:"The scope attribute identifies whether a header applies to a row or column."}],
references:[{label:"MDN: HTML table basics",url:"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content/HTML_table_basics"},{label:"W3C WAI: Tables",url:"https://www.w3.org/WAI/tutorials/tables/"}]
},
{
slug:"audio-video-and-embedded-media",title:"Audio, video and embedded media",summary:"Add native media players and understand captions, fallbacks and embeds.",minutes:20,
objectives:["Use audio and video elements with sources.","Explain why captions and transcripts matter.","Embed external content with appropriate restrictions."],
sections:[
{title:"Use native media elements",body:"HTML provides audio and video elements for media playback without requiring a third-party player. The controls attribute exposes browser playback controls. Provide meaningful fallback text between the opening and closing tags for browsers that cannot use the element. Media sources can be supplied with src or with one or more source elements when different formats are available.",code:'<video controls width="640" poster="/media/preview.jpg">\n  <source src="/media/lesson.mp4" type="video/mp4">\n  <track kind="captions" src="/media/lesson-en.vtt" srclang="en" label="English" default>\n  Your browser does not support HTML video.\n</video>'},
{title:"Make media accessible",body:"Captions communicate spoken dialogue and meaningful sounds to people who cannot hear the audio. Transcripts provide a text version that can be read, searched and translated. Audio descriptions can communicate important visual information that is not already present in the soundtrack. Do not rely on autoplay with sound; unexpected playback can be disruptive and create accessibility problems."},
{title:"Choose formats and sources deliberately",body:"The source element lets the browser select a supported media format. Include accurate type values when known. Large media files affect loading and bandwidth, so compress them appropriately and avoid downloading media before a visitor needs it. The preload attribute can influence browser loading, but it is a hint rather than a guarantee."},
{title:"Embedding third-party content",body:"The iframe element embeds another browsing context, such as a video player or map. Give each iframe a descriptive title. Only embed content from providers you trust, because embedded content can introduce privacy, performance and security considerations. Use sandbox restrictions when the embedded experience does not need broad permissions.",note:"A video player is not accessible simply because it has controls. Captions, keyboard operation and understandable alternatives still matter."}],
exercise:{prompt:"Add a video player to a lesson page with controls, a poster image, captions and fallback text.",requirements:["Use the video element with controls.","Provide a source with a type.","Provide a captions track with srclang and label.","Include fallback text."],solution:'<video controls poster="/media/preview.jpg">\n  <source src="/media/demo.mp4" type="video/mp4">\n  <track kind="captions" src="/media/demo-en.vtt" srclang="en" label="English">\n  Your browser cannot play this video.\n</video>'},
quiz:[{question:"What does a captions track provide?",options:["A thumbnail image","Text for dialogue and meaningful sounds","A faster download","A video poster"],answer:1,explanation:"Captions make spoken content and relevant audio information available as text."},{question:"What should an iframe have to help identify its content?",options:["A descriptive title","A password","A table caption","An h1 inside the parent page"],answer:0,explanation:"A descriptive title gives users of assistive technology context about the embedded browsing context."}],
references:[{label:"MDN: Video and audio content",url:"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content/HTML_video_and_audio"},{label:"W3C WAI: Captions",url:"https://www.w3.org/WAI/media/av/captions/"}]
},
{
slug:"figures-and-content-grouping",title:"Figures, quotations and content grouping",summary:"Use figure, figcaption, blockquote, pre and other grouping elements appropriately.",minutes:16,
objectives:["Group media with captions using figure.","Mark quotations with blockquote and q.","Represent code and preformatted text correctly."],
sections:[
{title:"Figures connect media and captions",body:"The figure element groups self-contained content such as an image, diagram, code sample or chart that is referenced from the main text. A figcaption provides its caption. The figure can be moved elsewhere in the document without making the surrounding text nonsensical. Not every image needs a figure: use a simple img when a separate caption is not useful.",code:'<figure>\n  <img src="/images/html-tree.png" alt="Diagram of nested HTML elements">\n  <figcaption>An HTML document forms a nested element tree.</figcaption>\n</figure>'},
{title:"Quotations should be marked as quotations",body:"Use blockquote for an extended quotation and q for a short quotation embedded in a sentence. The cite attribute can record the source URL, while a visible citation should identify the source for readers. The cite element represents the title of a cited work; it is not a generic way to style an author name."},
{title:"Code and preformatted content",body:"The code element identifies a fragment of computer code. The pre element preserves whitespace and line breaks, making it useful for code examples when combined with code. For inline code, use code without pre. Use samp for sample output and kbd for user keyboard input when those distinctions help explain a technical process.",code:'<p>Run <code>npm run build</code> in your terminal.</p>\n<pre><code>const greeting = "Hello";\nconsole.log(greeting);</code></pre>\n<p>Press <kbd>Ctrl</kbd> + <kbd>S</kbd> to save.</p>'},
{title:"Choose elements by meaning",body:"HTML includes many elements for grouping and text semantics, but more markup is not automatically better. Use elements when their meaning adds clarity. Do not use blockquote just to indent text or pre just to preserve a visual layout. CSS is responsible for presentation; semantic elements should reflect the content.",note:"Inspect the document outline and ask whether each element describes the content accurately."}],
exercise:{prompt:"Create an article with a figure and caption, a quotation with attribution, and a multi-line code example.",requirements:["Wrap an image in figure.","Add a figcaption.","Use blockquote for the quotation.","Use pre and code for the multi-line example."],solution:'<article><h1>HTML elements</h1>\n<figure><img src="/images/dom.png" alt="Nested element tree"><figcaption>A simplified document tree.</figcaption></figure>\n<blockquote><p>Good structure gives content meaning.</p></blockquote>\n<pre><code>&lt;h1&gt;Hello&lt;/h1&gt;</code></pre></article>'},
quiz:[{question:"Which element provides a caption for a figure?",options:["caption","figcaption","legend","summary"],answer:1,explanation:"figcaption is the caption associated with a figure element."},{question:"Which element is suitable for an inline code fragment?",options:["code","pre only","kbd only","samp only"],answer:0,explanation:"The code element identifies a code fragment and can be used inline or inside pre for a block."}],
references:[{label:"MDN: Content sectioning and text semantics",url:"https://developer.mozilla.org/en-US/docs/Web/HTML/Element"}]
},
{
slug:"html-metadata-and-social-sharing",title:"Document metadata and social sharing",summary:"Write useful titles, descriptions, canonical URLs and sharing metadata.",minutes:18,
objectives:["Distinguish visible content from head metadata.","Write descriptive titles and meta descriptions.","Understand canonical links and social preview metadata."],
sections:[
{title:"The head describes the document",body:"The head contains metadata and supporting resources rather than the main visible page content. A page title is essential: it appears in browser tabs and often becomes the clickable title in search results. Titles should be unique, descriptive and concise enough to identify the page. The meta description can summarise the page for search and sharing systems, although search engines may choose a different snippet."},
{title:"Character encoding and viewport",body:"Declare UTF-8 early with a charset meta element so text is interpreted consistently. The viewport meta element helps mobile browsers use the device width rather than a wide virtual layout viewport. Do not disable zoom with user-scalable=no; visitors need to be able to enlarge content.",code:'<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>HTML Tables: Accessible Data | Example</title>\n  <meta name="description" content="Learn to structure accessible HTML tables with captions and headers.">\n  <link rel="canonical" href="https://example.com/learn/html/tables/">\n</head>'},
{title:"Canonical URLs and duplicate pages",body:"A canonical link indicates the preferred URL for a page when similar or duplicate versions exist. It is a signal, not an instruction that guarantees a search engine will select that URL. Use an absolute URL that points to the intended canonical page. Do not canonicalise unrelated pages to a single homepage."},
{title:"Social previews and metadata quality",body:"Open Graph metadata can provide a title, description, URL and image for social sharing previews. These fields should describe the actual page and use image URLs that can be fetched by the sharing platform. Metadata does not replace useful on-page content. Search visibility depends on many factors; no meta tag guarantees ranking or approval.",note:"Write the title and description for a human deciding whether the page is relevant. Avoid repeating keywords unnaturally."}],
exercise:{prompt:"Write the head metadata for a tutorial about accessible HTML tables.",requirements:["Add UTF-8 charset and responsive viewport.","Write a unique descriptive title.","Add a useful meta description.","Add an absolute canonical URL."],solution:'<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Accessible HTML Tables | Example</title>\n<meta name="description" content="Learn how to create clear, accessible tables using captions and header cells.">\n<link rel="canonical" href="https://example.com/guides/html-tables/">\n</head>'},
quiz:[{question:"Where does the document title belong?",options:["Inside body","Inside head","Inside footer","Inside nav"],answer:1,explanation:"The title element belongs in the document head."},{question:"What does a canonical link communicate?",options:["The page's colour palette","A preferred URL for similar or duplicate pages","A browser language","A required search ranking"],answer:1,explanation:"Canonical metadata indicates a preferred URL but does not guarantee search engine selection."}],
references:[{label:"MDN: What is metadata?",url:"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content/Webpage_metadata"},{label:"Google Search Central: Canonical URLs",url:"https://developers.google.com/search/docs/crawling-indexing/consolidate-duplicate-urls"}]
},
{
slug:"global-attributes-and-data-attributes",title:"Global attributes, IDs and data attributes",summary:"Use common attributes to identify, label and configure HTML elements.",minutes:16,
objectives:["Use id and class appropriately.","Understand title, hidden, lang and tabindex.","Store custom element data with data attributes."],
sections:[
{title:"Attributes add information",body:"Global attributes can be used on many HTML elements. id gives an element a unique identifier within the document. class groups elements for styling or scripting. lang can identify a language change within a page. title can provide advisory information, but should not be the only way essential instructions are communicated. Attribute values should be meaningful and valid for their purpose."},
{title:"IDs and classes are not interchangeable",body:"An id should be unique on a page and is useful for fragment links, labels and scripting hooks. A class can be shared by many elements and is commonly used to apply styles to a group. Avoid using an id for every style rule: classes make components easier to reuse. Keep names descriptive and avoid spaces inside a single id value.",code:'<nav aria-label="Lesson navigation">\n  <a class="nav-link" href="#examples">Examples</a>\n</nav>\n<section id="examples" class="lesson-section">\n  <h2>Examples</h2>\n</section>'},
{title:"Data attributes for custom information",body:"Attributes beginning with data- let authors attach custom information to an element. They are often used by scripts to connect a control with a small piece of configuration. They should not be used to hide sensitive information: anything in the HTML can be inspected by visitors. Prefer semantic attributes and native HTML behaviour when they already express the required meaning.",code:'<button type="button" data-action="expand" data-panel="lesson-notes">Show notes</button>'},
{title:"Hidden and keyboard focus",body:"The hidden attribute indicates that an element is not currently relevant and should not be presented. It is not a substitute for secure access control. tabindex can influence keyboard focus: tabindex=0 places an element in the normal focus order, while negative values can make it programmatically focusable without adding it to sequential tab navigation. Avoid positive tabindex values because they create confusing focus order.",note:"Use a real button for actions and a real link for navigation instead of adding tabindex and click handlers to generic elements."}],
exercise:{prompt:"Create a navigation link to a section and add a button with a data attribute.",requirements:["Give the target section a unique id.","Link to the section using a fragment URL.","Use a reusable class name.","Add a data-action attribute to a button."],solution:'<a class="nav-link" href="#resources">Resources</a>\n<section id="resources" class="content-section"><h2>Resources</h2></section>\n<button type="button" data-action="save">Save</button>'},
quiz:[{question:"Which attribute should uniquely identify one element in a document?",options:["class","id","style","data"],answer:1,explanation:"An id value should be unique within the document."},{question:"Should sensitive information be stored in data attributes?",options:["Yes, they are encrypted","Only on mobile","No, HTML can be inspected by visitors","Yes, if the element is hidden"],answer:2,explanation:"Data attributes are part of the document and are not a secure storage mechanism."}],
references:[{label:"MDN: Global attributes",url:"https://developer.mozilla.org/en-US/docs/Web/HTML/Global_attributes"}]
},
{
slug:"html-accessibility-foundations",title:"HTML accessibility foundations",summary:"Build inclusive pages with keyboard access, names, landmarks and text alternatives.",minutes:22,
objectives:["Explain accessible names and semantic roles.","Check keyboard access and focus order.","Use accessible names, labels and image alternatives."],
sections:[
{title:"Accessibility starts with good HTML",body:"Accessible HTML allows people to use content with different devices, abilities and assistive technologies. Semantic elements expose useful roles and relationships to browsers. A button announces itself as a button; a heading can be navigated as a heading; a label identifies a form control. Replacing native elements with generic containers often removes these built-in behaviours."},
{title:"Keyboard interaction and focus",body:"Every interactive control should be reachable and operable using a keyboard. Links and buttons are naturally keyboard accessible. Focus should be visible so users can tell where they are. Avoid removing outlines without providing a clear replacement. Do not create keyboard traps where a visitor cannot move away from a component."},
{title:"Names, labels and alternatives",body:"Controls need accessible names that explain their purpose. Visible labels are the preferred way to identify form fields. Images need alt text based on their purpose: informative images need useful descriptions, decorative images usually use empty alt text, and complex diagrams may need a longer explanation nearby. Link text should make sense when encountered out of context."},
{title:"Structure and language",body:"Use headings in a logical hierarchy, landmark elements for major page regions and lang attributes for the document language or language changes. Use lists for grouped items and tables for tabular data. Colour alone should not communicate meaning. Accessibility is not a one-time checklist; test with keyboard navigation, zoom, different devices and assistive technology where possible.",note:"Automated checkers can catch some issues but cannot decide whether alt text is meaningful or whether the content order makes sense."}],
exercise:{prompt:"Audit a simple page and improve its keyboard and screen-reader structure.",requirements:["Add lang to html.","Use header, nav, main and footer landmarks.","Ensure links have descriptive text.","Ensure every form control has a label.","Give informative images useful alt text."],solution:'<html lang="en"><body><header><h1>Course notes</h1></header><nav aria-label="Primary"><a href="/learn">Browse lessons</a></nav><main><img src="/notes.jpg" alt="Notebook showing a labelled HTML outline"><form><label for="email">Email</label><input id="email" type="email"></form></main><footer>Learning resources</footer></body></html>'},
quiz:[{question:"What should you do before adding ARIA roles to a custom control?",options:["Use a native HTML element if one fits","Remove all labels","Add tabindex=5","Hide the control"],answer:0,explanation:"Native HTML provides built-in semantics and keyboard behaviour, so it should be preferred whenever possible."},{question:"What is the correct alt text for a purely decorative image?",options:["The image filename","A long description of its colours","An empty alt attribute","No img element"],answer:2,explanation:"An empty alt attribute tells assistive technology the image can be ignored because it adds no information."}],
references:[{label:"W3C WAI: Easy Checks",url:"https://www.w3.org/WAI/test-evaluate/preliminary/"},{label:"MDN: Accessibility",url:"https://developer.mozilla.org/en-US/docs/Web/Accessibility"}]
},
{
slug:"html-validation-and-debugging",title:"Validate and debug HTML",summary:"Find structural errors, inspect the DOM and build a repeatable debugging workflow.",minutes:20,
objectives:["Distinguish source markup from the browser DOM.","Use browser developer tools to inspect elements.","Validate markup and diagnose common mistakes."],
sections:[
{title:"A page rendering does not prove it is correct",body:"Browsers attempt to recover from malformed HTML so that visitors can still see content. As a result, missing closing tags or invalid nesting may produce a page that appears mostly correct while the browser has repaired the structure in unexpected ways. Validation helps identify errors and warnings before they become harder to diagnose."},
{title:"Inspect the DOM in developer tools",body:"The Elements or Inspector panel shows the DOM tree the browser created, which may differ from the source you wrote because the parser repairs certain mistakes. Select an element to inspect its attributes and computed context. Use the Console to spot script errors, and the Network panel to find missing images, stylesheets or other resources."},
{title:"Common HTML mistakes",body:"Frequent problems include duplicate ids, missing alt attributes, invalid nesting, labels that do not match input ids, links without meaningful destinations, and headings chosen only for their appearance. Check the browser console and network errors, then reduce the page to the smallest example that still demonstrates the problem."},
{title:"Build a reliable debugging loop",body:"Reproduce the issue, inspect the relevant element, form a specific hypothesis, make one change and test again. Validate the document after structural changes. Test links and forms manually, and check keyboard behaviour. Keep examples small enough that another developer can understand what is happening.",note:"A validator reports technical conformance issues, but human review is still needed for meaning, usability and accessibility."}],
exercise:{prompt:"Debug a page containing duplicate ids, an unlabelled input and an image without alt text.",requirements:["Give each id a unique value.","Associate a label with the input.","Add appropriate alt text to the image.","Validate the corrected markup."],solution:'<img src="/profile.jpg" alt="Portrait of the course instructor">\n<label for="student-email">Email</label><input id="student-email" name="email" type="email">\n<section id="profile"><h2>Profile</h2></section>'},
quiz:[{question:"Why can malformed HTML still appear to work in a browser?",options:["Browsers repair some markup errors","HTML has no rules","The server rewrites all pages","CSS fixes every nesting issue"],answer:0,explanation:"Browsers use error-recovery rules to construct a DOM even when source markup is malformed."},{question:"Which tool helps identify missing image and stylesheet requests?",options:["Network panel","Page title","Table caption","Viewport meta"],answer:0,explanation:"The Network panel shows requests and their status, helping locate missing resources."}],
references:[{label:"Nu HTML Checker",url:"https://validator.w3.org/nu/"},{label:"Chrome DevTools: Elements",url:"https://developer.chrome.com/docs/devtools/dom/"}]
},
{
slug:"html-document-architecture",title:"Plan a multi-page website",summary:"Organise pages, navigation, reusable structure and relative file paths.",minutes:20,
objectives:["Plan a simple site map.","Use relative URLs for local pages and assets.","Create consistent navigation across pages."],
sections:[
{title:"Plan before writing markup",body:"A multi-page website needs a clear information architecture. Start by listing the pages visitors need and grouping related content. A small personal site might include Home, About, Projects and Contact. Draw a simple site map and decide which links belong in the primary navigation. Good information architecture prevents a collection of pages from becoming a maze."},
{title:"Understand file and URL paths",body:"A relative URL is resolved from the current document location. If index.html links to about.html in the same folder, the href can be about.html. A root-relative URL begins with a slash and resolves from the site root. Paths such as ../assets/logo.svg move up one directory. Case sensitivity can differ between local development systems and production hosting, so match file names exactly."},
{title:"Keep navigation consistent",body:"Use the same navigation structure across related pages so visitors can predict where links will be. Give navigation landmarks accessible names when a page contains more than one. Indicate the current page in a way that is not communicated by colour alone, and ensure the current page link remains understandable."},
{title:"Shared structure and maintainability",body:"A site header, primary navigation, main content and footer provide a repeatable page frame. In a static site generator, layouts and components can share that frame without copying the same markup into every page. Even in plain HTML, consistent structure and file naming make the site easier to update.",note:"Test every link from the page where it appears. A path that works from the homepage may be wrong when used from a nested folder."}],
exercise:{prompt:"Plan a three-page personal website and write the navigation for each page.",requirements:["Create Home, About and Contact page links.","Use meaningful link text.","Use a nav landmark with an accessible label.","Use valid relative paths between pages."],solution:'<nav aria-label="Primary navigation">\n<a href="index.html">Home</a>\n<a href="about.html">About</a>\n<a href="contact.html">Contact</a>\n</nav>'},
quiz:[{question:"What does ../ mean in a relative path?",options:["Move into the next folder","Move up one directory","Open a new tab","Load the homepage"],answer:1,explanation:"The .. path segment refers to the parent directory."},{question:"Why keep primary navigation consistent across pages?",options:["It reduces image size","It makes navigation predictable","It replaces headings","It guarantees SEO ranking"],answer:1,explanation:"Consistent navigation helps visitors understand the site and move between pages."}],
references:[{label:"MDN: Creating navigation menus",url:"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content/Navigation_menus"}]
},
{
slug:"interactive-html-elements",title:"Interactive HTML elements",summary:"Use details, summary, dialog and native controls for common interactions.",minutes:19,
objectives:["Create disclosure widgets with details and summary.","Understand dialog and its accessibility requirements.","Prefer native interactive elements where appropriate."],
sections:[
{title:"Disclosure widgets with details",body:"The details element creates a disclosure widget that visitors can expand or collapse. Its first summary child provides the visible label. This is useful for supplementary explanations, FAQs and optional details. Native behaviour includes keyboard interaction and an exposed expanded or collapsed state, reducing the amount of custom scripting required.",code:'<details>\n  <summary>What is semantic HTML?</summary>\n  <p>HTML that communicates the meaning and role of content.</p>\n</details>'},
{title:"Dialog boxes",body:"The dialog element represents a dialog box or other interactive component. It can be shown modally with showModal() or non-modally with show(). A modal dialog places the rest of the page behind a modal interaction. Provide a clear heading, a way to close it, and sensible focus handling. Do not use a dialog when a simple link or inline disclosure is enough."},
{title:"Native controls reduce custom code",body:"Buttons, select elements, input types and details provide built-in interaction patterns. Native controls generally work with keyboard and assistive technology more reliably than improvised clickable div elements. Custom scripting may still be needed for application behaviour, but start with the closest native element."},
{title:"Progressive enhancement",body:"A useful page should communicate its main content even if a script fails or has not loaded yet. Use HTML to provide the structure and basic content, then add JavaScript for enhancements. If a component requires JavaScript to reveal essential content, ensure that failure states are considered and that controls do not appear functional when they are not.",note:"Test interactive controls using only the keyboard. Native HTML elements are a good starting point, not a substitute for testing."}],
exercise:{prompt:"Build an FAQ section using native disclosure widgets.",requirements:["Use a section with a heading.","Create at least two details elements.","Give each details a meaningful summary.","Put the answer content inside details."],solution:'<section><h2>Frequently asked questions</h2>\n<details><summary>Do I need coding experience?</summary><p>No. Start with the first lesson.</p></details>\n<details><summary>Can I practise in the browser?</summary><p>Yes, use the guided workspace.</p></details></section>'},
quiz:[{question:"Which element supplies the visible label for details?",options:["summary","caption","legend","label"],answer:0,explanation:"The summary element labels the disclosure widget."},{question:"What does showModal() do on a dialog?",options:["Hides it permanently","Opens it as a modal dialog","Submits a form","Changes the page language"],answer:1,explanation:"showModal() opens a dialog in the top layer and makes the rest of the document modal."}],
references:[{label:"MDN: details element",url:"https://developer.mozilla.org/en-US/docs/Web/HTML/Element/details"},{label:"MDN: dialog element",url:"https://developer.mozilla.org/en-US/docs/Web/HTML/Element/dialog"}]
},
{
slug:"html-and-css-javascript-relationship",title:"Connect HTML with CSS and JavaScript",summary:"Load stylesheets and scripts responsibly and understand progressive enhancement.",minutes:18,
objectives:["Link external CSS files.","Load external JavaScript with defer or modules.","Keep structure, presentation and behaviour separate."],
sections:[
{title:"HTML is the document foundation",body:"HTML defines the structure and meaning of a page. CSS controls visual presentation and layout. JavaScript adds behaviour and can update the DOM. Keeping these concerns separate helps teams maintain and test their websites. A well-structured HTML document should still communicate its core content if styling is unavailable."},
{title:"Connect an external stylesheet",body:"Use a link element in the head with rel stylesheet and an href pointing to the CSS file. External stylesheets can be reused across pages and cached by the browser. Keep paths correct and avoid duplicating large blocks of inline style declarations when a shared stylesheet is more appropriate.",code:'<head>\n  <link rel="stylesheet" href="/assets/css/site.css">\n</head>'},
{title:"Load JavaScript thoughtfully",body:"The script element can load an external JavaScript file. A classic script with defer downloads without blocking HTML parsing and runs after the document has been parsed. Module scripts are deferred by default and support import and export. Avoid placing large blocking scripts at the top of the document without a clear reason.",code:'<script src="/assets/js/site.js" defer></script>\n<script type="module" src="/assets/js/app.js"></script>'},
{title:"Progressive enhancement and failure handling",body:"Build the essential content and navigation in HTML first. Add CSS to improve presentation and JavaScript to enhance interaction. If a script fails, visitors should still be able to understand the page and access important information. Avoid using JavaScript to create basic headings, paragraphs and links that could exist in the original HTML.",note:"A useful debugging habit is to disable JavaScript and confirm that the page still communicates its essential purpose."}],
exercise:{prompt:"Create a document head that links one external stylesheet and one deferred JavaScript file.",requirements:["Use link rel stylesheet.","Use a correct stylesheet href.","Load a script with defer.","Keep the scripts and styles in the head."],solution:'<head>\n<meta charset="UTF-8">\n<title>My site</title>\n<link rel="stylesheet" href="/css/site.css">\n<script src="/js/site.js" defer></script>\n</head>'},
quiz:[{question:"What is the main role of CSS?",options:["Document structure","Visual presentation","Database storage","URL routing"],answer:1,explanation:"CSS controls presentation, while HTML provides structure and meaning."},{question:"What does defer do for a classic external script?",options:["Runs it before parsing starts","Defers execution until parsing is complete","Deletes the script","Makes it a CSS file"],answer:1,explanation:"A deferred classic script downloads in parallel and executes after document parsing."}],
references:[{label:"MDN: Applying CSS to HTML",url:"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Styling_basics/Getting_started"},{label:"MDN: Script element",url:"https://developer.mozilla.org/en-US/docs/Web/HTML/Element/script"}]
},
{
slug:"html-security-and-safe-embedding",title:"HTML security and safe embedding",summary:"Understand form destinations, iframe sandboxing, link relationships and untrusted content.",minutes:20,
objectives:["Recognise why HTML alone cannot secure user input.","Use iframe sandbox restrictions thoughtfully.","Understand safe external link and embedding practices."],
sections:[
{title:"HTML is not a security boundary",body:"Hiding an element, disabling a button or adding a client-side required attribute does not protect data. Visitors can inspect and modify their browser-side HTML. Any data sent to a server must be validated and safely processed by that server. Never put passwords, API keys or private configuration into HTML source or data attributes."},
{title:"Sandbox embedded content",body:"An iframe creates a separate browsing context. The sandbox attribute applies restrictions to embedded content, and individual permissions can be granted only when required. Avoid combining powerful sandbox permissions without understanding their effect. For an editor preview, keep the preview isolated and do not grant same-origin access or top-navigation privileges unless there is a compelling, reviewed need.",code:'<iframe title="Preview of learner page" sandbox="allow-scripts" srcdoc="<h1>Hello</h1>"></iframe>'},
{title:"External links and embedded providers",body:"Only embed content from providers you trust. Third-party embeds can observe requests and may add tracking, scripts or other resources. Use privacy-conscious embed options where available and explain what visitors are opening. For links that open new tabs, rel=noopener can prevent the opened page from accessing the original window through window.opener."},
{title:"Treat user-generated markup as untrusted",body:"If an application accepts HTML from users, it must consider script injection and other unsafe markup. Rendering untrusted HTML directly into a page can create cross-site scripting vulnerabilities. A safe preview should isolate the document and avoid exposing the parent application's origin or privileged APIs. Never evaluate learner code on the server just to display a preview.",note:"The LearnLab workspace uses a sandboxed browser preview. It is a learning environment, not a production hosting service."}],
exercise:{prompt:"Create a safe isolated preview iframe and an external reference link.",requirements:["Give the iframe a descriptive title.","Use the sandbox attribute with only required permissions.","Use an HTTPS external URL.","Use rel noopener for a link that opens a new tab."],solution:'<iframe title="HTML exercise preview" sandbox="allow-scripts" srcdoc="<h1>Preview</h1>"></iframe>\n<a href="https://developer.mozilla.org/" target="_blank" rel="noopener">MDN documentation</a>'},
quiz:[{question:"Does the required attribute secure data submitted to a server?",options:["Yes, completely","No, server-side validation is still required","Only for email fields","Only when the page is HTTPS"],answer:1,explanation:"Client-side validation can be bypassed. The server must validate all submitted data."},{question:"Why sandbox an HTML preview iframe?",options:["To make text bold","To restrict what embedded content can do","To improve image resolution","To add a page title"],answer:1,explanation:"Sandbox restrictions limit the capabilities of embedded content and help isolate it."}],
references:[{label:"MDN: iframe sandbox",url:"https://developer.mozilla.org/en-US/docs/Web/HTML/Element/iframe#sandbox"},{label:"OWASP: Cross Site Scripting Prevention",url:"https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html"}]
},
{
slug:"html-capstone-and-publishing-checklist",title:"Capstone: Build and review a complete website",summary:"Combine your HTML skills into a polished multi-section project and prepare it for publishing.",minutes:35,
objectives:["Plan and build a complete semantic page.","Review accessibility, metadata, forms and media.","Validate and prepare the site for publication."],
sections:[
{title:"Plan the content and page outline",body:"Start with the audience and purpose. Decide what a visitor should understand or do after arriving. Sketch the heading outline before writing markup. Identify the main sections, navigation links, images, tables or forms the page genuinely needs. Gather content and assets before coding so the page is coherent rather than a collection of unrelated examples."},
{title:"Build the page from structure outward",body:"Create a valid document skeleton with language, character encoding, viewport and a descriptive title. Add header, navigation, main content and footer landmarks. Use headings, paragraphs, lists, links and figures to express the content. Add forms only when there is a real destination and a clear reason to collect information. Keep each section focused on one purpose."},
{title:"Review quality and accessibility",body:"Check that every image has an appropriate alt value, every form control has a label, links describe their destinations and heading levels form a logical outline. Navigate the page with a keyboard. Zoom in and inspect narrow screen layouts. Validate the HTML and use developer tools to check missing resources and console errors."},
{title:"Prepare for publishing",body:"Check titles and descriptions, canonical URLs, internal links and asset paths. Confirm that media has captions or alternatives where appropriate. Test every page from its actual hosted URL because relative paths can behave differently in nested directories. Make sure forms point to a real service and explain how submissions are handled. A static HTML form does not send messages unless a backend or form provider receives them.",note:"Before publishing, ask a person unfamiliar with the project to use it. Watch where they hesitate; those moments often reveal missing context or unclear navigation."}],
exercise:{prompt:"Build and review your personal profile website using all the skills from this course.",requirements:["Use valid document structure and descriptive metadata.","Use semantic landmarks and a logical heading hierarchy.","Include descriptive links, appropriate images and a useful list.","Include an accessible form only if a working submission destination exists.","Validate the markup and test keyboard navigation."],solution:'<!doctype html>\n<html lang="en">\n<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Alex Morgan | Personal Profile</title><meta name="description" content="Projects, interests and contact information for Alex Morgan."></head>\n<body><header><h1>Alex Morgan</h1></header><nav aria-label="Primary"><a href="#about">About</a><a href="#projects">Projects</a></nav><main><section id="about"><h2>About</h2><p>I enjoy learning how the web works.</p><ul><li>Design</li><li>Reading</li><li>Technology</li></ul></section><section id="projects"><h2>Projects</h2><p><a href="https://developer.mozilla.org/">Explore web documentation</a></p></section></main><footer><p>Personal learning project</p></footer></body></html>'},
quiz:[{question:"What should you do before publishing a form?",options:["Assume HTML sends the message","Confirm that a real endpoint receives and handles submissions","Remove all labels","Hide the submit button"],answer:1,explanation:"A form needs a functioning server or service to receive and process its submission."},{question:"Which is the strongest final quality check?",options:["Only inspect the page colour","Validate markup, test keyboard access and check real hosted paths","Only check the title","Only count the elements"],answer:1,explanation:"A useful release check combines technical validation with real interaction and accessibility testing."}],
references:[{label:"MDN: HTML learning area",url:"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content"},{label:"W3C WAI: Evaluating web accessibility",url:"https://www.w3.org/WAI/test-evaluate/"}]
}
];
courses[0].lessons.push(...extendedHtmlLessons);


